class Solution:
    def findSecretWord(self, words: List[str], master: 'Master') -> None:
        n = len(words)
        M = [[sum(a[i] == b[i] for i in range(6)) for b in words] for a in words]
        cand = list(range(n))
        while len(cand) > 1:
            best, bestScore = cand[0], float('inf')
            for c in cand:
                cnt = [0] * 7
                for x in cand:
                    cnt[M[c][x]] += 1
                score = max(cnt[k] - (1 if k == M[c][c] else 0) for k in range(7))
                if score < bestScore:
                    best, bestScore = c, score
            g = words[best]
            k = master.guess(g)
            if k == 6:
                return
            cand = [x for x in cand if M[best][x] == k]
        master.guess(words[cand[0]])

