class Solution {
public:
    void findSecretWord(vector<string>& words, Master& master) {
        int n = words.size();
        vector<vector<int>> M(n, vector<int>(n));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                int m = 0;
                for (int p = 0; p < 6; p++) if (words[i][p] == words[j][p]) m++;
                M[i][j] = m;
            }
        vector<int> cand(n);
        iota(cand.begin(), cand.end(), 0);
        while (cand.size() > 1) {
            int best = cand[0], bestScore = INT_MAX;
            for (int c : cand) {
                array<int,7> cnt{};
                for (int x : cand) cnt[M[c][x]]++;
                int score = 0;
                for (int k = 0; k <= 6; k++)
                    score = max(score, cnt[k] - (k == M[c][c] ? 1 : 0));
                if (score < bestScore) { bestScore = score; best = c; }
            }
            string g = words[best];
            int k = master.guess(g);
            if (k == 6) return;
            vector<int> next;
            for (int x : cand) if (M[best][x] == k) next.push_back(x);
            cand = next;
        }
        master.guess(words[cand[0]]);
    }
};

