class Solution {
    public void findSecretWord(String[] words, Master master) {
        int n = words.length;
        int[][] M = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                int m = 0;
                for (int p = 0; p < 6; p++) if (words[i].charAt(p) == words[j].charAt(p)) m++;
                M[i][j] = m;
            }
        List<Integer> cand = new ArrayList<>();
        for (int i = 0; i < n; i++) cand.add(i);
        while (cand.size() > 1) {
            int best = cand.get(0), bestScore = Integer.MAX_VALUE;
            for (int c : cand) {
                int[] cnt = new int[7];
                for (int x : cand) cnt[M[c][x]]++;
                int score = 0;
                for (int k = 0; k <= 6; k++)
                    score = Math.max(score, cnt[k] - (k == M[c][c] ? 1 : 0));
                if (score < bestScore) { bestScore = score; best = c; }
            }
            String g = words[best];
            int k = master.guess(g);
            if (k == 6) return;
            List<Integer> next = new ArrayList<>();
            for (int x : cand) if (M[best][x] == k) next.add(x);
            cand = next;
        }
        master.guess(words[cand.get(0)]);
    }
}

