var findSecretWord = function(words, master) {
    const n = words.length;
    const M = Array.from({length: n}, (_, i) =>
        Array.from({length: n}, (_, j) => {
            let m = 0;
            for (let p = 0; p < 6; p++) if (words[i][p] === words[j][p]) m++;
            return m;
        }));
    let cand = [...Array(n).keys()];
    while (cand.length > 1) {
        let best = cand[0], bestScore = Infinity;
        for (const c of cand) {
            const cnt = new Array(7).fill(0);
            for (const x of cand) cnt[M[c][x]]++;
            let score = 0;
            for (let k = 0; k <= 6; k++)
                score = Math.max(score, cnt[k] - (k === M[c][c] ? 1 : 0));
            if (score < bestScore) { bestScore = score; best = c; }
        }
        const g = words[best];
        const k = master.guess(g);
        if (k === 6) return;
        cand = cand.filter(x => M[best][x] === k);
    }
    master.guess(words[cand[0]]);
};
